import{_ as o,c as e,o as r,ae as n}from"./chunks/framework.Bi6zybwU.js";const d=JSON.parse('{"title":"Import Ninja Tables JSON","description":"Import Ninja Tables JSON","frontmatter":{"title":"Import Ninja Tables JSON","description":"Import Ninja Tables JSON"},"headers":[],"relativePath":"guide/import-export/import-ninja-tables-json.md","filePath":"guide/import-export/import-ninja-tables-json.md"}'),a={name:"guide/import-export/import-ninja-tables-json.md"};function s(i,t,l,p,g,m){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="import-ninja-tables-json" tabindex="-1">Import Ninja Tables JSON <a class="header-anchor" href="#import-ninja-tables-json" aria-label="Permalink to &quot;Import Ninja Tables JSON&quot;">​</a></h1><p>Ninja Tables can import JSON file from an existing table of the plugin into another table. Importing <strong>JSON</strong> to your table using Ninja** **Tables is a simple and quick process. This plugin is intended to make things easier for users and to improve the overall user experience.</p><h2 id="import-json-file" tabindex="-1">Import JSON File <a class="header-anchor" href="#import-json-file" aria-label="Permalink to &quot;Import JSON File&quot;">​</a></h2><p>Let’s dive into the simple guide to learn how to <strong>import JSON</strong> file.</p><ul><li>First, navigate to the **Ninja Tables dashboard **and click on the **Import Table **button on the top right of the screen.</li><li>To know how to <strong>Export Data (CSV/JSON)</strong>, you can get help from <a href="https://ninjatables.com/docs/export-ninja-tables-csv-json/" target="_blank" rel="noreferrer">here</a>.</li><li>Now, go to the **Import <strong>button</strong> **(on the left), and you will get an <strong>Import</strong> <strong>Format</strong> field, where you can choose your desired <strong>JSON</strong> <strong>(Exported From Ninja</strong> <strong>Tables)</strong> table format. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Ninja-Tables-Pro-%E2%80%B9-North-%E2%80%94-WordPress-06-02-2025_04_07_PM-scaled.webp" alt="Import Format"></li><li>Upload your <strong>Exported</strong> <strong>JSON</strong> file (from Ninja Tables) in the **Select File **area by clicking on the <strong>Choose</strong> <strong>File</strong> button and then set the <strong>Import</strong> <strong>Format</strong> as a <strong>JSON (Exported From Ninja Table)</strong>.</li><li>You can also upload your <strong>Exported</strong> <strong>JSON/CSV</strong> file (from Drag &amp; Drop Tables) in the Select File area by clicking on the Choose File button and then setting the <strong>Import</strong> <strong>Format</strong> as a <strong>JSON (Exported From Ninja Table)</strong>.</li><li>Lastly, click on the **Import **button when you are done! Exporting the JSON file lets you export the Table Styling with the table data. This is how easy it is to import JSON file in Ninja Tables.</li></ul>',5)])])}const b=o(a,[["render",s]]);export{d as __pageData,b as default};
